#include "resultant_lib.hpp"
int main(int argc,char**argv){if(argc<3){cerr<<"usage: build_resultants square_equations.txt output.txt\n";return 2;}try{init();selfchecks();for(int n=1;n<10;n++)for(int m=1;m<10;m++)for(int da=0;da<3;da++)for(int db=0;db<3;db++){Pol a(max(0,m+1-da)),b(max(0,n+1-db));for(auto&v:a)v=rand()%QF;for(auto&v:b)v=rand()%QF;if(formal_resultant(a,b,m,n)!=syl(a,b,m,n))throw runtime_error("formal resultant mismatch");}cerr<<"PASS formal resultant specializations\n";ifstream in(argv[1]);if(!in)throw runtime_error("cannot open input file");Pol l=readp(in);int ne;in>>ne;vector<BP>eq(ne);for(auto&p:eq)p=readbp(in);for(int s:{0,1,5,25}){vector<Pol>special(ne);for(int j=0;j<ne;j++)for(auto&r:eq[j].r)special[j].push_back(ev(r,s));for(int j=1;j<ne;j++)cerr<<"s="<<s<<" gcd(55,"<<55+j<<") degree "<<gcdp(special[0],special[j]).size()-1<<"\n";}
vector<pair<int,int>>pairs{{0,1},{0,2}};ofstream out(argv[2]);if(!out)throw runtime_error("cannot open output file");printp(out,l);out<<pairs.size()<<'\n';vector<Pol>reds;Pol combined;for(auto [ia,ib]:pairs){int m=eq[ia].r.size()-1,n=eq[ib].r.size()-1;int bound=n*(eq[ia].ns()-1)+m*(eq[ib].ns()-1);int N=bound+1;cerr<<"PAIR "<<ia<<' '<<ib<<" bound "<<bound<<" N "<<N<<"\n";vector<Pol>evA,evB;for(auto&r:eq[ia].r)evA.push_back(geom_eval(r,N));for(auto&r:eq[ib].r)evB.push_back(geom_eval(r,N));cerr<<"evaluated all coefficients\n";Pol vals(N);for(int i=0;i<N;i++){Pol a(m+1),b(n+1);for(int j=0;j<=m;j++)a[j]=evA[j][i];for(int j=0;j<=n;j++)b[j]=evB[j][i];vals[i]=formal_resultant(a,b,m,n);}cerr<<"evaluated all resultants; first "<<vals[0]<<"\n";Pol R=geom_interpolate(vals);cerr<<"interpolated degree "<<R.size()-1<<"\n";if(R.empty()){cerr<<"IDENTICALLY ZERO RESULTANT\n";out<<ia<<' '<<ib<<' '<<bound<<'\n';printp(out,R);printp(out,R);continue;}
// Verify every interpolation node, plus extra points outside the geometric grid.
if(geom_eval(R,N)!=vals)throw runtime_error("resultant interpolation");for(int i=0;i<8;i++){F s=ex[(N+7*i+13)%NN];Pol a,b;for(auto&r:eq[ia].r)a.push_back(ev(r,s));for(auto&r:eq[ib].r)b.push_back(ev(r,s));if(ev(R,s)!=formal_resultant(a,b,m,n))throw runtime_error("extra resultant point");}cerr<<"PASS resultant identity grid and extra nodes\n";Pol red=saturation(R,l);Pol lm=pscale(l,inv(l.back()));if(pscale(fastmul(ppower(lm,756),red),R.back())!=R)throw runtime_error("ell^756 factor identity failed");cerr<<"PASS exact ell_monic^756 factor identity\n";cerr<<"SATURATED degree "<<red.size()-1<<"\n";reds.push_back(red);combined=fastgcd(combined,red);cerr<<"COMBINED GCD degree "<<combined.size()-1<<"\n";out<<ia<<' '<<ib<<' '<<bound<<'\n';printp(out,R);printp(out,red);out.flush();if(combined==Pol{1}){cerr<<"UNIT GCD: no common geometric solution on l!=0\n";break;}}
if(combined!=Pol{1})throw runtime_error("generic unit-gcd exclusion not established");printp(out,combined);cerr<<"DONE resultant computations\n";
return 0;}catch(exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
